#!/usr/bin/env bash
# Export the Swagger generated by the running backend (springdoc) and diff it against the contract.
#   export-swagger.sh --base http://localhost:8091 --ms Mxx [--out dir]
# Writes <out>/openapi-exported.yaml, <out>/openapi-exported.json and <out>/swagger-diff.md.
# Exit code 1 if an operation of milestones <= Mxx is missing or differs.
source "$(dirname "$0")/lib.sh"
BASE_URL="http://localhost:8091" MS="" OUT=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --base) BASE_URL="$2"; shift 2;;
    --ms) MS="$2"; shift 2;;
    --out) OUT="$2"; shift 2;;
    -h|--help) sed -n '2,5p' "$QF_SELF"; exit 0;;
    *) die "unknown option $1";;
  esac
done
[[ -n "$MS" ]] || die "--ms required"
OUT="${OUT:-loops/backend-dev/outputs/evidence/$MS}"
mkdir -p "$OUT"
curl -fsS "$BASE_URL/v3/api-docs.yaml" -o "$OUT/openapi-exported.yaml" || die "could not fetch $BASE_URL/v3/api-docs.yaml"
curl -fsS "$BASE_URL/v3/api-docs" -o "$OUT/openapi-exported.json" || die "could not fetch $BASE_URL/v3/api-docs"
SPEC_DIR="$(loopctl get-spec)"
loopctl swagger-diff --contract "$SPEC_DIR/contracts/openapi.yaml" --exported "$OUT/openapi-exported.json" --ms "$MS" --out "$OUT/swagger-diff.md"
